import { Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  // Geometry matching the texture aspect ratio (512:320 = 1.6:1)
  const width = 1.6;
  const height = 1;
  const geometry = new PlaneGeometry(width, height);

  // Material – no lighting required for a static plane
  const material = new MeshBasicNodeMaterial({ color: '#ffffff' });

  const mesh = new Mesh(geometry, material);
  mesh.name = 'pricing-card-2';

  // Load the brushed-metal map texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.needsUpdate = true;
      material.map = tex;
      material.needsUpdate = true;
      // Store reference for cleanup
      mesh.userData._texture = tex;
    }).catch(() => {
      // Fallback: use a flat surface color from the palette
      material.color.setHex(0x0b0b10);
    });
  } else {
    // No image provided – use surface color
    material.color.setHex(0x0b0b10);
  }

  // Event handlers (none for this node)
  mesh.userData.handlers = {};

  // Cleanup: dispose geometry, material, and loaded texture
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (mesh.userData._texture) {
      mesh.userData._texture.dispose();
    }
    // No GSAP timelines to kill
  };

  return mesh;
}
